const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Indus River floodplain region in Pakistan (Sindh province area)
  const indusRegion = ee.Geometry.Polygon([
    [[67.5, 24.0], [69.5, 24.0], [69.5, 28.0], [67.5, 28.0], [67.5, 24.0]]
  ]);

  // Define time periods
  const date1 = '2022-07-01';
  const date2 = '2022-08-28';

  // Function to get water extent for a specific date
  function getWaterExtent(targetDate) {
    const col = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(indusRegion)
      .filterDate(ee.Date(targetDate).advance(-3, 'day'), ee.Date(targetDate).advance(3, 'day'))
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .select('VV');

    return col;
  }

  // Get collections for both dates
  const col1 = getWaterExtent(date1);
  const col2 = getWaterExtent(date2);

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`July 1 images: ${size1}`);
  console.log(`August 28 images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log('No Sentinel-1 data for one or both dates.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Create mosaics and detect water (VV < -15 dB)
  const img1 = col1.median();
  const img2 = col2.median();

  const water1 = img1.lt(-15);
  const water2 = img2.lt(-15);

  // Calculate water extent in square meters
  const pixelArea = ee.Image.pixelArea();

  const waterExtent1Obj = await water1.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: indusRegion,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const waterExtent2Obj = await water2.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: indusRegion,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const waterExtent1 = waterExtent1Obj.VV;
  const waterExtent2 = waterExtent2Obj.VV;

  // Count valid pixels
  const count1Obj = await water1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: indusRegion,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const count1 = count1Obj.VV;

  if (count1 === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (waterExtent1 === null || waterExtent2 === null || 
      waterExtent1 === undefined || waterExtent2 === undefined ||
      isNaN(waterExtent1) || isNaN(waterExtent2)) {
    console.log('Calculation failed - invalid results.');
    console.log('<answer>C3</answer>');
    return;
  }

  const extent1_km2 = (waterExtent1 / 1e6).toFixed(2);
  const extent2_km2 = (waterExtent2 / 1e6).toFixed(2);
  const change = ((waterExtent2 - waterExtent1) / 1e6).toFixed(2);
  const pctChange = (((waterExtent2 - waterExtent1) / waterExtent1) * 100).toFixed(1);

  console.log(`July 1 water: ${extent1_km2} km2`);
  console.log(`Aug 28 water: ${extent2_km2} km2`);
  console.log(`Change: +${change} km2 (${pctChange}%)`);

  if (waterExtent2 > waterExtent1) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
